            { interval: "30,000 km", timeLimit: "2 years", task: "Cabin Microfilter", details: "Replace the HVAC cabin filter to maintain blower motor efficiency and interior air quality.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "35 EUR" }
