            { interval: "60,000 km", timeLimit: "4 years", task: "Spark Plug Replacement", details: "Replace all six spark plugs to maintain smooth V6 idle quality, prevent ignition breakdown under the higher cylinder pressures of the 3.5L, and optimize fuel efficiency.", parts: ["6x NGK/Bosch Plugs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" },
            { interval: "80,000 km", timeLimit: "5 years", task: "Ignition Coil Evaluation", details: "Test coil output and resistance. Replace any degraded coils or the complete set if misfires, rough running, or fuel trim issues are present.", parts: ["6x Coil Packs"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "240 EUR" },
            { interval: "100,000 km", timeLimit: "6 years", task: "Intake Manifold Flap Inspection", details: "Check variable intake manifold flaps and linkage for seizure, breakage, or detachment. Early intervention prevents complete manifold replacement.", parts: ["Inspection / Repair Kit"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "80-350 EUR" },
            { interval: "100,000 km", timeLimit: "6 years", task: "Balance Shaft Verification", details: "On any engine with uncertain history, verify balance shaft gear condition via diagnostic inspection or borescope. 2009+ engines generally have the updated design.", parts: ["Diagnostic inspection"], importance: "High", laborDifficulty: "Expert", estimatedCost: "100-200 EUR" },
            { interval: "Every Service", timeLimit: "1 year", task: "PCV / Crankcase Ventilation Inspection", details: "Inspect the breather system, oil separator, and valve cover area for excessive pressure, oil mist, or vacuum leaks that could accelerate seal wear or intake contamination.", parts: ["Inspection only"], importance: "High", laborDifficulty: "Easy", estimatedCost: "0 EUR" }
